out.mkdir(parents=True,exist_ok=True)
pdfmetrics.registerFont(TTFont('Arial','C:/Windows/Fonts/arial.ttf'))
pdfmetrics.registerFont(TTFont('ArialBold','C:/Windows/Fonts/arialbd.ttf'))
ink=colors.HexColor('#18392d'); orange=colors.HexColor('#f86a12'); pale=colors.HexColor('#eef5e9'); muted=colors.HexColor('#52665a')
W,H=A4; CW=W-88
styles={
 'title':ParagraphStyle('title',fontName='ArialBold',fontSize=25,leading=29,textColor=ink,spaceAfter=10),
 'h':ParagraphStyle('h',fontName='ArialBold',fontSize=16,leading=19,textColor=ink,spaceAfter=9),
 'h2':ParagraphStyle('h2',fontName='ArialBold',fontSize=11,leading=14,textColor=ink,spaceBefore=5,spaceAfter=5,keepWithNext=True),
 'body':ParagraphStyle('body',fontName='Arial',fontSize=9.5,leading=13.2,textColor=ink,spaceAfter=6),
 'small':ParagraphStyle('small',fontName='Arial',fontSize=8,leading=11,textColor=muted,spaceAfter=5),
 'step':ParagraphStyle('step',fontName='Arial',fontSize=9.5,leading=13.5,leftIndent=20,firstLineIndent=-18,textColor=ink,spaceAfter=6),
 'cell':ParagraphStyle('cell',fontName='ArialBold',fontSize=8.7,leading=11,textColor=ink,alignment=1),
}
def p(t,style='body'):
 return Paragraph(html.escape(t),styles[style])
def steps(items):
 return [p(str(i)+'.  '+v,'step') for i,v in enumerate(items,1)]
def note(label,text):
 t=Table([[p(label,'h2'),p(text)]],colWidths=[60,CW-60],hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),pale),('LINEBEFORE',(0,0),(0,-1),3,orange),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
 return t
def flow(items):
 cells=[p(x,'cell') for x in items]
 t=Table([cells],colWidths=[CW/len(cells)]*len(cells))
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),pale),('BOX',(0,0),(-1,-1),.7,colors.HexColor('#c5d9bf')),('INNERGRID',(0,0),(-1,-1),.6,colors.white),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),10)]))
 return t
def section(title,items): return [p(title,'h2'),*steps(items)]
def screenshot(name,width=CW):
 path=root/'docs'/'facility-guide-images'/name
 im=PILImage.open(path); w,h=im.size
 return Image(str(path),width=width,height=width*h/w)
def footer(c,d):
 c.setStrokeColor(orange);c.line(44,36,W-44,36);c.setFont('Arial',8);c.setFillColor(muted)
 c.drawString(44,23,'STOR24  |  FACILITIES  |  26 NOVEMBER 2026')
 c.drawRightString(W-44,23,str(d.page))
def build(name,pages):
 story=[]
 for i,page in enumerate(pages):
  if i: story.append(PageBreak())
  story.extend(page)
 SimpleDocTemplate(str(out/name),pagesize=A4,leftMargin=44,rightMargin=44,topMargin=40,bottomMargin=48,title=name).build(story,onFirstPage=footer,onLaterPages=footer)

